const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toastEl=document.querySelector('#toast');
const state={user:null,csrf:'',workspace:null,page:null,run:null,filter:'all',busy:false};
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',audit:'M9 3h6v4H9z M6 5H4v16h16V5h-2 M8 12l2 2 5-5 M8 18h8',connections:'M8 3H5v7h3 M16 3h3v7h-3 M5 7h14 M12 10v11 M8 18h8',explorer:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',monitor:'M3 4v16h18 M5 14l4-5 4 4 6-8',standards:'M4 3h12l4 4v14H4z M14 3v6h6 M8 13h8 M8 17h6',reports:'M4 3h16v18H4z M8 8h8 M8 12h8 M8 16h5',gate:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',activity:'M3 12h4l3-8 4 16 3-8h4',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 4v16 M4 12h16',play:'M8 4l13 8-13 8z',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',info:'M12 8v1 M12 12v5 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M5 12l4 4L20 5',close:'M5 5l14 14 M5 19L19 5',clock:'M12 7v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chevron:'M9 5l7 7-7 7',logout:'M9 3H4v18h5 M12 12h10 M17 7l5 5-5 5',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const badge=(text,kind=text)=>`<span class="badge ${e(String(kind).toLowerCase())}">${e(String(text).replaceAll('_',' '))}</span>`;
const date=v=>v?new Date(v).toLocaleString('en-GB',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Not recorded';
const ago=v=>v?date(v):'Not measured';
const button=(text,action,cls='',data='')=>`<button class="btn ${cls}" data-action="${action}" ${data}>${text}</button>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">${icon('audit')}</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
function toast(s){toastEl.textContent=s;toastEl.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.style.display='none',5500)}
async function api(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf,...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});const data=await r.json();if(!r.ok){if(r.status===401&&url!='/api/login'){clearSession();login()}throw Error(data.error||'Request failed')}return data}
function modal(title,body){document.querySelector('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button(icon('close'),'close','quiet','aria-label="Close dialog"')}</div><div class="dialog-content">${body}</div>`;dialog.showModal()}
function head(eyebrow,title,description,actions=''){return `<header class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="buttons">${actions}</div></header>`}
function notice(title,text,amber=false){return `<div class="notice ${amber?'amber':''}">${icon('info')}<div><b>${title}</b><p>${text}</p></div></div>`}
const rolePolicies={
 operator:{title:'Operator workspace',home:'overview',pages:['overview','audit','connections','explorer','oversight','monitor','reports','standards','gate','activity']},
 bank:{title:'Bank engineer workspace',home:'audit',pages:['audit','connections','monitor','reports','standards','gate','activity']},
 tpp:{title:'TPP developer workspace',home:'explorer',pages:['explorer','activity']},
 reviewer:{title:'Oversight workspace',home:'oversight',pages:['oversight','audit','monitor','reports','activity']},
 standards:{title:'Standards reviewer workspace',home:'standards',pages:['standards','activity']}
};
const policy=()=>rolePolicies[state.user?.role]||{title:'Restricted workspace',home:'activity',pages:['activity']};
const roleNav=()=>policy().pages.map(key=>nav.find(([id])=>id===key)).filter(Boolean);
function activateSession(result){state.user=result.user;state.csrf=result.csrf;state.workspace=null;state.run=null;state.filter='all';state.page=policy().home;}
function clearSession(){state.user=null;state.csrf='';state.workspace=null;state.run=null;state.filter='all';state.page=null;if(dialog.open)dialog.close();}
function navigate(page){state.page=policy().pages.includes(page)?page:policy().home;state.filter='all';render();}
const canRun=()=>['operator','bank'].includes(state.user.role);
const canReview=()=>['operator','standards'].includes(state.user.role);
const nav=[['overview','Overview'],['audit','Audit center'],['connections','Connections'],['explorer','TPP explorer'],['oversight','Oversight dashboard'],['monitor','Monitoring'],['reports','Reports'],['standards','Standards & rules'],['gate','Release gates'],['activity','Activity log']];
function shell(body){const w=state.workspace;const allowedNav=roleNav();const workNav=allowedNav.filter(([k])=>!['standards','gate','activity'].includes(k));const governNav=allowedNav.filter(([k])=>['standards','gate','activity'].includes(k));app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">≋</div><span>GeoBridge<small>Open banking assurance</small></span></div><div class="nav-label">${e(policy().title.toUpperCase())}</div>${workNav.map(([k,t])=>`<button class="nav-item ${state.page===k?'active':''}" data-nav="${k}">${icon(k)}${t}</button>`).join('')}${governNav.length?'<div class="nav-label">GOVERNANCE</div>':''}${governNav.map(([k,t])=>`<button class="nav-item ${state.page===k?'active':''}" data-nav="${k}">${icon(k)}${t}</button>`).join('')}<div class="side-foot"><div class="local-tag"><i class="dot"></i> Local development workspace</div><p>Synthetic data only.<br>Evidence before claims.</p></div></aside><main class="main"><div class="topbar"><select class="mobile-menu" aria-label="Navigate workspace" id="mobile-nav">${allowedNav.map(([k,t])=>`<option value="${k}" ${state.page===k?'selected':''}>${t}</option>`).join('')}</select><div class="breadcrumb">Workspace <span style="margin:0 12px">/</span><b>${nav.find(x=>x[0]===state.page)?.[1]||'Audit detail'}</b></div><div class="buttons"><span class="badge">SYNTHETIC ONLY</span><div class="userbox"><div class="avatar">${e(state.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong>${e(state.user.name)}</strong><small>${e(policy().title)}</small></div></div>${button(icon('logout'),'logout','quiet','aria-label="Sign out"')}</div></div><div class="content">${body}<div class="footer-line"><span>GeoBridge / Evidence-led interoperability</span><span>Build 0.1.0 · ${w?.ai.configured?'Live AI configured':'AI template fallback'} · No certification claims</span></div></div></main></div>`}
function login(){app.innerHTML=`<div class="login"><section class="login-story"><div class="brand"><div class="brand-mark">≋</div><span>GeoBridge<small>Open banking assurance</small></span></div><div><div class="eyebrow" style="color:#a3cccc">FROM API DIFFERENCES TO CLEAR EVIDENCE</div><h1>Trust the connection.<br><em>Understand the difference.</em></h1><div class="login-lines">${[35,58,45,75,60,87,68,96,80,100].map(h=>`<span style="height:${h}%"></span>`).join('')}</div><p>Audit APIs against the right profile. Explain what needs fixing. Give developers one consistent contract.</p></div><footer>Independent hackathon prototype · Synthetic data only</footer></section><section class="login-form"><div class="login-form-inner"><div class="eyebrow">YOUR ASSURANCE WORKSPACE</div><h2>Welcome to GeoBridge</h2><p>Sign in with your assigned demo account.</p><form id="login-form"><div class="field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" placeholder="e.g. operator" required></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" placeholder="Your local demo password" required></div><button class="btn primary" type="submit">Sign in ${icon('arrow')}</button><div class="error" id="login-error" role="alert"></div></form><div class="divider"></div><p class="smalltext">Accounts are created locally for the bank engineer, TPP developer, oversight and standards reviewers.</p><p class="footnote">Your generated credentials are in <code>data/demo-credentials.json</code> inside the project folder. No public registration.</p></div></section></div>`;document.querySelector('#login-form').onsubmit=async ev=>{ev.preventDefault();const b=Object.fromEntries(new FormData(ev.target));try{const result=await api('/api/login',{method:'POST',body:b});activateSession(result);await refresh()}catch(err){document.querySelector('#login-error')?document.querySelector('#login-error').textContent=err.message:toast(err.message)}}}
async function refresh(){state.workspace=await api('/api/workspace');render()}
function metric(label,value,note,ic='monitor',highlight=false){return `<div class="card metric ${highlight?'highlight':''}"><div class="label">${label}${icon(ic)}</div><div class="value">${value}</div><div class="note">${note}</div></div>`}
function overview(){const w=state.workspace,completed=w.runs.filter(x=>x.status==='completed'),last=completed[0];return head('ASSURANCE AT A GLANCE','A clearer view of every connection.','Test what applies. Keep the evidence. Make integration differences actionable.',canRun()?button(icon('play')+' Start an audit','new-run','primary'):'')+`<div class="grid four">${metric('Registered connections',w.connections.length,'No live adapter configured','connections')}${metric('Completed audit runs',completed.length,last?'Latest '+date(last.finishedAt):'Run platform assurance to begin','audit')}${metric('Reviewed bank rules',w.rules.filter(x=>x.status==='approved').length+'/'+w.rules.length,'Human approval required','standards')}${metric('Bank observations','—','Waiting for authorized sandbox access','monitor',true)}</div><div class="spacer"></div>${notice('Build evidence before declaring readiness.','Bank connections are pending. Platform assurance executes real local control tests; imported fixtures are always labelled separately.')}<div class="split space"><div class="card"><div class="card-head"><div><h2>Recent audit runs</h2><p>Reproducible results, with an explicit evidence source.</p></div>${button('View all '+icon('arrow'),'nav-audit','quiet')}</div>${runTable(w.runs.slice(0,4))}</div><div class="card pad"><div class="eyebrow">THE GEOBRIDGE WORKFLOW</div><h2>One story. Clear proof.</h2><div class="step"><span class="step-number">01</span><div><h3>Choose the right profile</h3><p>Pin the service, standard version and capabilities.</p></div></div><div class="step"><span class="step-number">02</span><div><h3>Run and inspect</h3><p>Open expected vs observed results and source evidence.</p></div></div><div class="step"><span class="step-number">03</span><div><h3>Explain and act</h3><p>Export both reports, retest a fix and check publication readiness.</p></div></div><div class="step"><span class="step-number">04</span><div><h3>Integrate consistently</h3><p>Use the common API when a verified bank adapter is connected.</p></div></div></div></div><div class="grid two space"><div class="card pad"><h2>Four layers, distinct evidence</h2>${['compatibility','reliability','latency','security'].map(l=>{const r=last?.counts||{};return `<div class="layer-row"><label>${e(l[0].toUpperCase()+l.slice(1))}</label><div class="bar"></div><small>${last?'View run':'No run'}</small></div>`}).join('')}<p class="smalltext">Local controls validate the platform. Bank quality requires actual sandbox samples.</p></div><div class="panel-summary"><div class="eyebrow">FOR THE TPP DEVELOPER</div><h2>A common contract.<br>Honest connection boundaries.</h2><p>Preview exact mappings for accounts, balances and transactions. Missing required data returns a typed error; unsupported operations never masquerade as empty success.</p><div class="spacer"></div>${button('Open TPP explorer '+icon('arrow'),'nav-explorer')}</div></div>`}
function runTable(runs){if(!runs.length)return empty(canRun()?'Your first audit starts here':'No audit evidence in your scope',canRun()?'Review a sandbox connection or import synthetic response evidence. Platform checks are local controls, not bank results.':'Authorized bank diagnostics will appear after runs are shared with your role.',canRun()?button('Start an audit','new-run','primary'):'');return `<div class="table-wrap"><table><thead><tr><th>Audit</th><th>Evidence</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr class="clickable" data-run="${r.id}"><td><b>${e(r.name)}</b><small>${e(r.profile)}</small></td><td>${badge(r.evidenceMode||r.kind)}</td><td>${badge(r.status)}</td><td class="subtle">${date(r.createdAt)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`}
function audit(){if(!canRun())return head('AUTHORIZED DIAGNOSTICS','Audit evidence','Inspect shared findings and coverage. This account cannot execute tests.',button('Compare runs','compare-runs'))+notice('Read-only oversight access.','Raw response payloads and customer account access are not granted by this role.')+'<div class="card space">'+runTable(state.workspace.runs)+'</div>';return head('TEST · EXPLAIN · RETEST',state.user.role==='bank'?'Your bank audits':'Audit center','Every run keeps its evidence mode, profile, rule versions and original results.',button('Compare runs','compare-runs')+(canRun()?button(icon('play')+' New audit','new-run','primary'):''))+`<div class="grid ${state.user.role==='operator'?'three':'two'}">${state.user.role==='operator'?`<div class="card pad"><div class="eyebrow">LOCAL ASSURANCE</div><h3>Verify the platform itself</h3><p>25 deterministic control checks. Real cryptographic verification, semantic preservation and measurement logic.</p><div class="spacer"></div>${canRun()?button('Run platform checks','run-platform','primary'):badge('Read-only account')}</div>`:''}<div class="card pad"><div class="eyebrow">RESPONSE EVIDENCE</div><h3>Inspect original API behavior</h3><p>Import synthetic captures or clearly labelled fixtures. Reviewed rules evaluate the original response.</p><div class="spacer"></div>${canRun()?button('Import evidence','import-evidence'):badge('Read-only account')}</div><div class="card pad"><div class="eyebrow">BANK SANDBOX</div><h3>Check connection readiness</h3><p>Missing bank setup is a blocker, never a pass. No external requests are made before the adapter is configured.</p><div class="spacer"></div>${badge('Access pending','blocked')}</div></div><div class="card space"><div class="card-head"><div><h2>Audit history</h2><p>Click a run to inspect findings and exports.</p></div>${button(icon('clock')+' Refresh','refresh','small')}</div>${runTable(state.workspace.runs)}</div>`}
function oversight(){
 const w=state.workspace,runs=w.runs.filter(r=>r.status==='completed'&&r.kind!=='platform');
 const latest=new Map();for(const r of runs)if(!latest.has(r.connectionId||r.packId||r.id))latest.set(r.connectionId||r.packId||r.id,r);
 const cohort=[...latest.values()];const count=k=>cohort.reduce((n,r)=>n+(r.counts?.[k]||0),0);
 return head('AUTHORIZED BANK SCOPES','Oversight dashboard','Compare observed quality, inspect deviations and understand coverage. This is a read-only review workspace.')+
 `<div class="grid four">${metric('Visible bank connections',w.connections.length,'Explicit development review scope','connections')}${metric('Evidence runs',runs.length,'Platform self-tests excluded','audit')}${metric('Failed selected checks',count('FAIL'),'Not an overall bank rating','reports')}${metric('Unresolved checks',count('BLOCKED')+count('NEEDS_REVIEW')+count('NOT_ASSESSED'),'Latest visible evidence per target','standards')}</div><div class="space">${notice('Evidence source matters.','Uploaded fixtures and captures remain labelled. No production uptime, certification or endorsement is implied.')}</div><div class="card space"><div class="card-head"><div><h2>Coverage & findings</h2><p>Read original expectations and results; raw account and transaction payloads are not shared.</p></div>${button('Open evidence','nav-audit')}</div>${runTable(runs)}</div><div class="grid two space"><div class="panel-summary"><div class="eyebrow">QUALITY REVIEW</div><h2>Compare equivalent observations.</h2><p>Use the same profile, operation and measurement method. Unknown observations stay unknown; short probes do not establish monthly uptime.</p><div class="spacer"></div>${button('Review quality & history','nav-monitor')}</div><div class="card pad"><div class="eyebrow">ACTIONABLE REPORTS</div><h2>Trace a finding to its evidence.</h2><p>Inspect source locators, expected vs observed behavior and remediation guidance. Bank testing and changes remain with the authorized bank team.</p><div class="spacer"></div>${button('Open reports','nav-reports')}</div></div>`;
}
function connections(){return head('AUTHORIZED TARGETS ONLY','Connections','Register a sandbox and its declared contract. Connectivity remains unverified until the bank integration is complete.',canRun()?button(icon('plus')+' Register connection','new-connection','primary'):'')+notice('No live bank is connected yet.','Uploaded specifications can be reviewed against selected approved static checks now. Certificates, signing, bank onboarding and authoritative consent are configured in the bank integration stage.')+`<div class="grid two space">${state.workspace.connections.map(c=>`<div class="card"><div class="card-head"><div><h2>${e(c.name)}</h2><p>${e(c.environment)} · ${e(c.tenant)}</p></div>${badge(c.status,'blocked')}</div><div class="pad"><div class="profile-chip">${e(state.workspace.profiles.find(p=>p.id===c.profile)?.name||c.profile)}</div><div class="chip-list">${Object.entries(c.capabilities).map(([k,v])=>`<span class="chip">${e(k)} · ${e(v)}</span>`).join('')}</div><div class="divider"></div><p class="smalltext">${c.baseUrl?e(c.baseUrl):'Sandbox URL not supplied'}</p><p class="mono" style="margin-top:10px">Spec ${c.specHash?e(c.specHash.slice(0,20))+'…':'not uploaded'}</p><div class="buttons space">${canRun()?button('Upload OpenAPI','upload-spec','small',`data-id="${c.id}"`)+(c.specHash?button('Review specification','run-spec','small',`data-id="${c.id}"`):'')+button('Check readiness','readiness','small',`data-id="${c.id}"`):''}</div></div></div>`).join('')||`<div class="card">${empty('No connections in your scope','Your role can only see explicitly authorized private connection details.')}</div>`}</div>`}
const mappingSamples={accounts:{accounts:[{resourceId:'synthetic-account-01',currency:'GEL',displayName:'Synthetic account',cashAccountType:'CACC'}]},balances:{balances:[{balanceAmount:{amount:'1250.50',currency:'GEL'},balanceType:'interimAvailable',referenceDate:'2026-10-20'},{balanceAmount:{amount:'1300.50',currency:'GEL'},balanceType:'interimBooked',referenceDate:'2026-10-20'}]},transactions:{transactions:{booked:[{transactionId:'synthetic-01',transactionAmount:{amount:'-25.50',currency:'GEL'},bookingDate:'2026-10-20'}],pending:[{transactionId:'synthetic-02',transactionAmount:{amount:'-10.00',currency:'GEL'}}]}}};
function explorer(){const catalog=state.workspace.catalog||[];return head('ONE CONTRACT · EXPLICIT ADAPTERS','TPP explorer','Understand the common response format before connecting an authorized bank.')+notice('Mapping preview is available. Bank calls are not connected.','This editor validates synthetic JSON locally through the backend. It does not request customer information or represent a bank response.')+`<div class="card space"><div class="card-head"><div><h2>Supported connections</h2><p>Published capabilities only. Private bank configuration is not shared.</p></div></div>${catalog.length?`<div class="table-wrap"><table><thead><tr><th>Connection</th><th>Status</th><th>Capabilities</th></tr></thead><tbody>${catalog.map(c=>`<tr><td>${e(c.name)}</td><td>${badge(c.status,'blocked')}</td><td>${Object.entries(c.capabilities||{}).map(([k,v])=>e(k)+': '+e(v)).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`:empty('No published connections yet','Bank adapters and authorization must be verified before live operations become available.')}</div><div class="grid two space"><div class="card"><div class="card-head"><div><h2>Common contract preview</h2><p>Try a valid response, then remove a currency to see the guardrail.</p></div>${badge('Synthetic preview')}</div><div class="pad"><div class="field"><label for="mapping-operation">Operation</label><select id="mapping-operation"><option value="balances">Get balances</option><option value="accounts">List accounts</option><option value="transactions">List transactions</option></select></div><div class="field"><label for="mapping-json">Original synthetic response</label><textarea id="mapping-json" style="min-height:290px">${e(JSON.stringify(mappingSamples.balances,null,2))}</textarea></div><div class="buttons">${button(icon('play')+' Validate & normalize','normalize','primary')}${button('Insert missing-currency fault','mapping-fault','small')}</div></div></div><div class="card"><div class="card-head"><div><h2>GeoBridge response</h2><p>Exact amounts. Preserved balance types. Typed failures.</p></div></div><div class="pad" id="mapping-result">${empty('Ready for your request','The response will come from the working backend mapper.')}</div></div></div><div class="card space"><div class="card-head"><h2>Bank-connected API</h2>${badge('Not connected','blocked')}</div><div class="pad"><div class="grid two"><div><h3>Proposed common endpoints</h3><a class="btn small" href="/api/contract" target="_blank" rel="noopener">Common OpenAPI JSON</a><pre class="code light">GET /bridge/v1/connections
GET /bridge/v1/connections/{id}/accounts
GET /bridge/v1/connections/{id}/accounts/{id}/balances
GET /bridge/v1/connections/{id}/accounts/{id}/transactions</pre></div><div><h3>Before serving bank data</h3><p>Each connection needs a bank-specific adapter, the TPP identity, supported permissions and an authoritative valid consent. Current bank requests return <code>BANK_NOT_CONNECTED</code>.</p><div class="spacer"></div>${['tpp','operator'].includes(state.user.role)?button('Check bank API response','bridge-check'):badge('TPP login required')}</div></div><div id="bridge-result"></div></div></div>`}
function monitoring(){const w=state.workspace;const captures=w.runs.filter(r=>r.status==='completed'&&r.metrics?.some(m=>m.attempts));return head('MEASURE WHAT YOU ACTUALLY OBSERVE','Monitoring','Schedules, observation windows and per-operation measurements—with clear freshness.',canRun()?button(icon('plus')+' Add schedule','new-schedule','primary'):'')+`<div class="grid three">${metric('Bank probe availability','—','No live bank probe history in your scope')}${metric('Bank response time','—','No live latency observations')}${metric('Active schedules',w.schedules.length,'Runs while the local server is running','clock')}</div><div class="card space"><div class="card-head"><div><h2>Observation history</h2><p>Unknown intervals stay grey. No monthly uptime is inferred.</p></div>${badge('No live observations')}</div><div class="pad"><div class="timeline">${Array.from({length:60},()=>'<i title="No observation"></i>').join('')}</div><div class="legend"><span class="good">Successful probe</span><span class="bad">Failed probe</span><span>No observation</span></div><div class="spacer"></div><p class="smalltext">Connect a bank adapter before enabling actual probes. Replaying captured evidence does not create new bank availability observations.</p></div></div>${canRun()?`<div class="card space"><div class="card-head"><h2>Scheduled jobs</h2></div>${w.schedules.length?`<div class="table-wrap"><table><thead><tr><th>Job</th><th>Interval</th><th>Next run</th><th>Last result</th><th></th></tr></thead><tbody>${w.schedules.map(s=>`<tr><td>${e(s.label)}</td><td>${s.minutes} min</td><td>${date(s.nextRun)}</td><td>${e(s.lastError|| (s.lastRun?'Scheduled successfully':'Waiting'))}</td><td>${canRun()?button('Remove','delete-schedule','small',`data-id="${s.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('No schedules yet','Schedule platform assurance, captured-evidence review, or a blocked readiness check. Actual probes are added with the bank adapter.')}</div>`:''}<div class="card space"><div class="card-head"><div><h2>Cross-connection measurement cohorts</h2><p>Compare only equivalent profiles, operations, datasets and observation windows.</p></div></div>${captures.length?`<div class="table-wrap"><table><thead><tr><th>Evidence run</th><th>Profile / mode</th><th>Operation</th><th>Attempts</th><th>p50 ms</th><th>p95 ms</th></tr></thead><tbody>${captures.flatMap(r=>r.metrics.filter(m=>m.attempts).map(m=>`<tr data-run="${r.id}" class="clickable"><td>${e(r.name)}<small>${date(r.finishedAt)}</small></td><td>${e(r.profile)}<small>${e(r.evidenceMode)}</small></td><td>${e(m.operation)}</td><td>${m.attempts}</td><td>${m.p50??'—'}</td><td>${m.p95??'Insufficient samples'}</td></tr>`)).join('')}</tbody></table></div>`:empty('No comparable observations yet','Connect banks or import declared synthetic sandbox captures. No comparison values are pre-filled.')}</div><div class="card space"><div class="card-head"><h2>Imported measurement reports</h2>${badge('Uploader-declared samples')}</div>${captures.length?runTable(captures):empty('No measurement samples imported','Quality reports require timestamped positive-request samples. The fictional example intentionally has no timings.')}</div>`}
function reports(){const runs=state.workspace.runs.filter(r=>r.status==='completed');return head('ACTIONABLE OUTPUTS','Reports','Two required report types, plus reproducible JSON results and raw sample CSV.')+`<div class="grid two"><div class="card report-card">${icon('reports')}<h2>Incompatibility report</h2><p>Expected vs observed, selected rule, source locator, impact, remediation guidance and evidence mode. Platform checks stay separate from bank findings.</p><div class="chip-list"><span class="chip">Source-linked</span><span class="chip">Printable HTML / PDF</span><span class="chip">JSON export</span></div></div><div class="card report-card">${icon('monitor')}<h2>Quality report</h2><p>Per-operation counts, failure categories, p50 and p95. Small samples and missing measurements remain visible. No invented regulatory thresholds.</p><div class="chip-list"><span class="chip">Raw sample CSV</span><span class="chip">Disclosed methodology</span><span class="chip">No fake uptime</span></div></div></div><div class="card space"><div class="card-head"><h2>Available report bundles</h2></div>${runs.length?`<div class="table-wrap"><table><thead><tr><th>Run</th><th>Evidence mode</th><th>Reports</th></tr></thead><tbody>${runs.map(r=>`<tr><td><b>${e(r.name)}</b><small>${date(r.finishedAt)}</small></td><td>${badge(r.evidenceMode)}</td><td><div class="buttons">${exportLink(r.id,'incompatibility','Findings')}${exportLink(r.id,'quality','Quality')}${exportLink(r.id,'json','JSON')}${canRun()?exportLink(r.id,'csv','CSV'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Reports follow completed runs','Start a local assurance run to generate your first actual report.',canRun()?button('Run platform checks','run-platform','primary'):'')}</div>`}
const exportLink=(id,type,label)=>`<a class="btn small" href="/api/runs/${e(id)}/export/${type}" target="_blank" rel="noopener">${icon('download')}${label}</a>`;
function standards(){const w=state.workspace;const governanceSummary=canReview()?`<div class="grid three space">${metric('Rules awaiting review',w.rules.filter(r=>r.status==='draft').length,'Read source conditions before approving','standards')}${metric('Approved rules',w.rules.filter(r=>r.status==='approved').length,'Versioned reviewer decisions','check')}${metric('Pinned source snapshots',w.sources.length,'Open exact Georgian source text','reports')}</div>`:'';return head('VERSIONED SOURCES · REVIEWED EXPECTATIONS',canReview()?'Standards review desk':'Applicable standards & rules','Source documents inform candidate checks. Human review controls activation.',canReview()?button(icon('plus')+' Compare source snapshot','source-update'):'')+governanceSummary+notice('Payment-account and loan/deposit profiles are different.','The uploaded index points payment-account AIS to XS2A 0.8.RC3. Newer AIS and consent rules are not automatically applied to payment accounts.')+`<div class="grid three space">${w.profiles.map(p=>`<div class="card pad"><h3>${e(p.name)}</h3>${badge(p.status)}<p class="smalltext" style="margin-top:12px">${e(p.note)}</p></div>`).join('')}</div><div class="card space"><div class="card-head"><div><h2>Candidate rule ledger</h2><p>Open the full source, record applicability and approve only the observable assertion.</p></div><span class="subtle">${w.rules.filter(r=>r.status==='approved').length} approved · ${w.rules.filter(r=>r.status==='draft').length} draft</span></div>${w.rules.map(r=>`<div class="rule-row"><div><h3>${e(r.id)} · ${e(r.title)}</h3><p>${e(r.profile)} · §${e(r.section)} · ${e(r.reviewNote)}</p></div><div class="buttons">${badge(r.status)}${button('Inspect','review-rule','small',`data-id="${r.id}"`)}</div></div>`).join('')}</div><h2 class="space">Pinned source snapshots</h2><div class="grid two space">${w.sources.map(s=>`<div class="card source-card"><h3>${e(s.name)}</h3><div class="mono">SHA-256 ${e(s.sha256)}</div><a class="btn small" target="_blank" rel="noopener" href="/api/sources?file=${encodeURIComponent(s.file)}">Open extracted source ${icon('arrow')}</a></div>`).join('')}</div>${w.updates.length?`<div class="card space"><div class="card-head"><h2>Proposed source changes</h2></div>${w.updates.map(x=>`<div class="pad"><h3>${e(x.title)} ${badge(x.status)}</h3><p>${e(x.notice)}</p><p class="smalltext">${(x.added||[]).length} added lines · ${(x.removed||[]).length} removed lines · ${(x.affectedRules||[]).length} candidate rules affected</p><details class="space"><summary>Inspect text diff</summary><pre class="code light">${e((x.added||[]).map(x=>'+ '+x).join('\n')+'\n'+(x.removed||[]).map(x=>'- '+x).join('\n'))}</pre></details></div>`).join('')}</div>`:''}`}
function gates(){const w=state.workspace;return head('REGRESSIONS BEFORE PUBLICATION','Release gates','Evaluate a candidate against a completed run. Incomplete bank coverage holds publication.',canRun()?button('Compare specifications','spec-diff')+button(icon('plus')+' Evaluate candidate','new-gate','primary'):'')+notice('This gate controls GeoBridge publication decisions only.','A failed check rejects the candidate. Missing applicable bank evidence holds it for review. It cannot prevent a bank from changing an external API.')+`<div class="card space"><div class="card-head"><h2>Candidate decisions</h2></div>${w.gates.length?`<div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Decision</th><th>Reason</th><th>Time</th></tr></thead><tbody>${w.gates.map(g=>`<tr><td><b>${e(g.name)}</b><small>${e(String(g.runId||'').slice(0,8))}</small></td><td>${badge(g.decision)}</td><td>${e(g.reason)}</td><td>${date(g.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No release candidates evaluated','Run the checks first, then evaluate a named candidate. Local platform success alone cannot approve a bank release.')}</div>`}
function detail(){const r=state.run;if(!r)return empty('Loading run','Fetching persisted evidence…');const counts=r.counts||{};return head('PERSISTED AUDIT EVIDENCE',e(r.name),`${e(r.profile)} · Created ${date(r.createdAt)}`,`<div class="buttons">${button('← Audit history','nav-audit')}${canRun()?button('Retest','retest','primary',`data-id="${r.id}"`):''}</div>`)+`<div class="card"><div class="result-banner"><div><h2>${badge(r.status)} <span class="subtle">${e(r.id)}</span></h2><p>${e(r.evidenceMode||r.kind)} · ${r.finishedAt?'Finished '+date(r.finishedAt):'Waiting for worker result'}</p></div>${['queued','running'].includes(r.status)&&canRun()?button('Stop run','stop-run','danger',`data-id="${r.id}"`):''}</div>${['queued','running'].includes(r.status)?'<div class="loading-line"></div>':''}</div>${r.error?`<div class="notice amber space">${e(r.error)}</div>`:''}<div class="mini-stat">${['PASS','FAIL','BLOCKED','NEEDS_REVIEW','NOT_ASSESSED','NOT_APPLICABLE'].map(k=>`<div><b>${counts[k]||0}</b>${badge(k)}</div>`).join('')}</div>${notice('Read the evidence mode before interpreting results.','Local platform checks validate GeoBridge controls. Imported fixtures and uploaded captures are not live bank tests. Passing selected checks is not overall compliance.')}<div class="tabs space"><button class="tab ${state.filter==='all'?'active':''}" data-filter="all">All checks</button>${['compatibility','reliability','latency','security'].map(l=>`<button class="tab ${state.filter===l?'active':''}" data-filter="${l}">${l[0].toUpperCase()+l.slice(1)}</button>`).join('')}<button class="tab ${state.filter==='metrics'?'active':''}" data-filter="metrics">Quality metrics</button></div>${state.filter==='metrics'?metricDetail(r):`<div class="card">${r.results?.filter(f=>state.filter==='all'||f.layer===state.filter).map(f=>`<div class="finding" data-finding="${e(f.id)}"><div style="color:var(--teal)">${icon(f.layer==='security'?'gate':'audit')}</div><div><h3>${e(f.title)}</h3><p>${e(f.observed)}</p><small class="subtle">${e(f.ruleId||f.id)} · ${e(f.basis||'Selected rule')}${f.section?' · §'+e(f.section):''}</small></div>${badge(f.verdict)}</div>`).join('')||empty('No results in this layer','The worker has not recorded any matching checks.')}</div>`}${r.status==='completed'?`<div class="buttons space">${exportLink(r.id,'incompatibility','Incompatibility report')}${exportLink(r.id,'quality','Quality report')}${exportLink(r.id,'json','Run JSON')}${canRun()?exportLink(r.id,'csv','Sample CSV'):''}</div><div class="card pad space"><h3>Run provenance</h3><p class="mono">Ruleset ${e(r.rulesetHash)}<br>Evidence ${e(r.evidenceHash||'Local platform controls; no bank response')}<br>Build ${e(r.build)}</p><p class="footnote">${(r.limitations||[]).map(e).join('<br>')}</p></div>`:''}`}
function metricDetail(r){return `<div class="card"><div class="card-head"><div><h2>Per-operation quality</h2><p>Successful positive-request timings only. No regulatory threshold configured.</p></div></div>${r.metrics?.some(m=>m.attempts)?`<div class="table-wrap"><table><thead><tr><th>Operation</th><th>Attempts</th><th>Success</th><th>Errors</th><th>Timeouts</th><th>p50</th><th>p95</th></tr></thead><tbody>${r.metrics.map(m=>`<tr><td>${e(m.operation)}</td><td>${m.attempts}</td><td>${m.successRate===null?'—':(m.successRate*100).toFixed(1)+'%'}</td><td>${m.errors}</td><td>${m.timeouts}</td><td>${m.p50===null?'—':m.p50+' ms'}</td><td>${m.p95===null?'Insufficient samples':m.p95+' ms'}</td></tr>`).join('')}</tbody></table></div>`:empty('No bank latency measurements','Internal test execution duration is not bank response time. Import timestamped measurement samples or connect a bank adapter.')}</div>`}
function render(){if(!state.user)return login();if(!policy().pages.includes(state.page)&&!(state.page==='detail'&&state.run&&policy().pages.includes('audit')))state.page=policy().home;const views={overview,audit,connections,explorer,oversight,monitor:monitoring,reports,standards,gate:gates,detail};if(state.page==='activity'){shell(head('WHO · WHAT · WHEN','Activity log','Permission-scoped events recorded by the backend.')+'<div id="activity-list" class="card">'+empty('Loading events','Retrieving the audit trail…')+'</div>');loadEvents().catch(err=>toast(err.message));return}shell((views[state.page]||overview)())}
async function loadEvents(){const rows=await api('/api/events');const el=document.querySelector('#activity-list');if(el)el.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Action</th><th>Actor</th><th>Target</th><th>When</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(r.action.replaceAll('_',' '))}</td><td>${e(r.actor)}</td><td class="mono">${e(r.target)}</td><td>${date(r.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No visible events','Events appear as you use the workspace.')}
async function showRun(id){state.run=await api('/api/runs/'+id);state.page='detail';state.filter='all';render()}
async function startRun(body){const r=await api('/api/runs',{method:'POST',body});dialog.close();await refresh();await showRun(r.id)}
function newRun(){modal('Start an audit',`<p>Select the evidence you actually have. Each mode is labelled in the result.</p><div class="field"><label for="run-kind">Audit mode</label><select id="run-kind">${state.user.role==='operator'?'<option value="platform">Platform assurance · real local control tests</option>':''}<option value="evidence">Uploaded evidence · offline response review</option><option value="bank">Sandbox readiness · blocked until connected</option></select></div><div class="field"><label for="run-pack">Evidence pack (for evidence review)</label><select id="run-pack"><option value="">Select imported evidence</option>${state.workspace.packs.map(p=>`<option value="${p.id}">${e(p.name)} · ${e(p.mode)}</option>`).join('')}</select></div><div class="field"><label for="run-connection">Sandbox connection (for readiness)</label><select id="run-connection">${state.workspace.connections.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select></div>${notice('No live bank calls in this version.','Platform assurance is executable now. Bank-specific integration is deliberately pending.')}<div class="buttons space">${button(icon('play')+' Execute selected audit','execute-run','primary')}${button('Import evidence first','import-evidence')}</div>`)}
function importEvidence(){modal('Import synthetic response evidence',`<p>Use the documented JSON format. Credentials and common identifiers are redacted before persistence.</p><div class="field"><label for="evidence-file">JSON file</label><input type="file" accept=".json,application/json" id="evidence-file"></div><div class="field"><label for="evidence-json">Evidence pack JSON</label><textarea id="evidence-json" style="min-height:230px" placeholder="Paste JSON or load the fictional example"></textarea></div><label class="check"><input type="checkbox" id="synthetic-confirm">I confirm all data is synthetic and the evidence mode accurately identifies fixtures or sandbox captures.</label><div class="buttons">${button('Load fictional example','load-example')}${button('Import evidence','save-evidence','primary')}</div><p class="footnote">The example has no timing samples. We do not manufacture performance results.</p>`)}
async function findingDetail(id){const r=state.run,f=r.results.find(x=>x.id===id);let raw='';if(canRun()&&r.packId&&f.observationIndex!==undefined){const p=await api('/api/packs/'+r.packId);raw=JSON.stringify(p.observations[f.observationIndex],null,2)}modal('Finding details',`<h3>${e(f.title)} ${badge(f.verdict)}</h3><p class="mono">${e(f.ruleId||f.id)} · ${e(f.basis||'Selected rule')} · ${e(r.evidenceMode)}</p><div class="detail-grid space"><div class="detail-block"><label>Expected</label>${e(f.expected)}</div><div class="detail-block"><label>Observed</label>${e(f.observed)}</div><div class="detail-block full"><label>Suggested action</label>${e(f.fix||'Review the recorded control assertions. Retest after any relevant implementation change.')}</div></div>${f.quote?`<div class="quote">${e(f.quote)}</div><p class="smalltext">${e(f.source)} · §${e(f.section)} · ${e(f.reviewNote)}</p>`:''}${raw?`<details class="space"><summary>Original redacted evidence</summary><pre class="code">${e(raw)}</pre></details>`:''}<div class="divider"></div><h3>Explanation assistance</h3><p class="smalltext">Verdicts stay deterministic. AI advice is bounded and may be incorrect.</p><div class="buttons space">${button('Explain in English','explain','small',`data-id="${e(f.id)}" data-language="en"`)}${button('განმარტება ქართულად','explain','small',`data-id="${e(f.id)}" data-language="ka"`)}</div><div id="explanation-result"></div><p class="footnote">Reproduce: select this run’s evidence pack and profile, then Retest. Raw sample CSV is available from the run.</p>`)}
async function reviewRule(id){const r=state.workspace.rules.find(x=>x.id===id);modal('Review source and applicability',`<h3>${e(r.id)} · ${e(r.title)} ${badge(r.status)}</h3><p class="smalltext">${e(r.profile)} · ${e(r.source)} · §${e(r.section)}</p><div class="quote">${e(r.quote)}</div><p>${e(r.fix)}</p><p class="footnote">${e(r.reviewNote)}<br>Source hash: ${e(r.sourceHash)}</p><a class="btn small space" target="_blank" rel="noopener" href="/api/sources?file=${encodeURIComponent(r.source)}">Read full source ${icon('arrow')}</a>${canReview()?`<div class="field"><label for="review-note">Reviewer applicability note</label><textarea id="review-note" placeholder="Record the account category, selected service, mandatory/conditional nature and observed assertion being approved."></textarea></div><label class="check"><input type="checkbox" id="review-confirm">I reviewed the source and conditions. This approval covers only the implemented observable assertion, not full legal compliance.</label><div class="buttons">${button('Approve rule','approve-rule','primary',`data-id="${r.id}"`)}${button('Keep as draft','draft-rule','',`data-id="${r.id}"`)}</div>`:notice('Reviewer access required','Use a standards reviewer account to approve executable rules.')}`)}
document.addEventListener('change',async ev=>{if(ev.target.id==='mobile-nav'){navigate(ev.target.value)}if(ev.target.id==='mapping-operation'){document.querySelector('#mapping-json').value=JSON.stringify(mappingSamples[ev.target.value],null,2)}if(ev.target.id==='evidence-file'){const f=ev.target.files[0];if(f){if(f.size>2e6)return toast('File exceeds 2 MB');document.querySelector('#evidence-json').value=await f.text()}}});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action],[data-nav],[data-run],[data-filter],[data-finding]');if(!el)return;try{
 if(el.dataset.nav){return navigate(el.dataset.nav)}if(el.dataset.run)return await showRun(el.dataset.run);if(el.dataset.filter){state.filter=el.dataset.filter;return render()}if(el.dataset.finding)return await findingDetail(el.dataset.finding);
 const a=el.dataset.action;if(a.startsWith('nav-')){return navigate(a.slice(4))}if(a==='close')return dialog.close();if(a==='refresh')return await refresh();if(a==='logout'){await api('/api/logout',{method:'POST'});clearSession();return login()}
 if(a==='compare-runs'){const rs=state.workspace.runs.filter(r=>r.status==='completed');const opts=rs.map(r=>`<option value="${r.id}">${e(r.name)} · ${date(r.finishedAt)}</option>`).join('');return modal('Compare equivalent audit runs',`<p>Choose the same profile and evidence mode. Changed rulesets and evidence hashes remain visible.</p><div class="field"><label for="compare-before">Before</label><select id="compare-before">${opts}</select></div><div class="field"><label for="compare-after">After</label><select id="compare-after">${opts}</select></div>${button('Compare verdicts','compare-execute','primary')}<div id="compare-result"></div>`)}
 if(a==='compare-execute'){const x=await api('/api/compare',{method:'POST',body:{before:document.querySelector('#compare-before').value,after:document.querySelector('#compare-after').value}});document.querySelector('#compare-result').innerHTML='<pre class="code space">'+e(JSON.stringify(x,null,2))+'</pre>';return}
 if(a==='spec-diff')return modal('Compare candidate OpenAPI specifications',`<p>Structural diff only. No external deployment or automatic normative inference.</p><div class="field"><label for="spec-before">Baseline OpenAPI JSON</label><textarea id="spec-before"></textarea></div><div class="field"><label for="spec-after">Candidate OpenAPI JSON</label><textarea id="spec-after"></textarea></div>${button('Compare endpoints','spec-diff-execute','primary')}<div id="spec-diff-result"></div>`);
 if(a==='spec-diff-execute'){const x=await api('/api/spec-diff',{method:'POST',body:{before:JSON.parse(document.querySelector('#spec-before').value),after:JSON.parse(document.querySelector('#spec-after').value)}});document.querySelector('#spec-diff-result').innerHTML='<pre class="code space">'+e(JSON.stringify(x,null,2))+'</pre>';return}
 if(a==='new-run')return newRun();if(a==='run-platform')return await startRun({kind:'platform'});if(a==='execute-run')return await startRun({kind:document.querySelector('#run-kind').value,packId:document.querySelector('#run-pack').value,connectionId:document.querySelector('#run-connection').value});
 if(a==='run-spec')return await startRun({kind:'spec',connectionId:el.dataset.id});if(a==='readiness')return await startRun({kind:'bank',connectionId:el.dataset.id});if(a==='retest'){const r=state.run;return await startRun({kind:r.kind,packId:r.packId,connectionId:r.connectionId})}
 if(a==='stop-run'){await api('/api/runs/'+el.dataset.id+'/stop',{method:'POST'});await showRun(el.dataset.id);return}
 if(a==='import-evidence')return importEvidence();if(a==='load-example'){document.querySelector('#evidence-json').value=JSON.stringify(await api('/api/example'),null,2);return}
 if(a==='save-evidence'){if(!document.querySelector('#synthetic-confirm').checked)throw Error('Confirm synthetic data first');const b=JSON.parse(document.querySelector('#evidence-json').value);const result=await api('/api/packs',{method:'POST',body:b});dialog.close();await refresh();toast('Evidence imported. Select it in New audit.');return}
 if(a==='normalize'){const b=JSON.parse(document.querySelector('#mapping-json').value);const result=await api('/api/normalize',{method:'POST',body:{synthetic:true,operation:document.querySelector('#mapping-operation').value,body:b}});document.querySelector('#mapping-result').innerHTML=badge('Validated','pass')+'<pre class="code space">'+e(JSON.stringify(result,null,2))+'</pre>';return}
 if(a==='mapping-fault'){const b=structuredClone(mappingSamples.balances);delete b.balances[0].balanceAmount.currency;document.querySelector('#mapping-operation').value='balances';document.querySelector('#mapping-json').value=JSON.stringify(b,null,2);return}
 if(a==='bridge-check'){try{const x=await api('/bridge/v1/connections/pending/accounts');document.querySelector('#bridge-result').innerHTML='<pre class="code">'+e(JSON.stringify(x,null,2))+'</pre>'}catch(err){document.querySelector('#bridge-result').innerHTML='<div class="notice amber space">'+e(err.message)+'</div>'}return}
 if(a==='new-connection')return modal('Register a sandbox connection',`<p>Registration stores metadata only. External targets also require an operator-configured host allowlist.</p><div class="field"><label for="connection-name">Connection name</label><input id="connection-name" placeholder="Assigned sandbox A"></div><div class="field"><label for="connection-profile">Applicable profile</label><select id="connection-profile">${state.workspace.profiles.filter(p=>p.id!=='platform').map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label for="connection-url">Sandbox HTTPS base URL (optional until supplied)</label><input id="connection-url" placeholder="https://sandbox.example"></div>${button('Register connection','save-connection','primary')}`);
 if(a==='save-connection'){await api('/api/connections',{method:'POST',body:{name:document.querySelector('#connection-name').value,profile:document.querySelector('#connection-profile').value,baseUrl:document.querySelector('#connection-url').value}});dialog.close();await refresh();return toast('Connection registered; connectivity remains unverified')}
 if(a==='upload-spec')return modal('Upload OpenAPI JSON',`<p>Remote references are not fetched. No secrets should be included.</p><div class="field"><label for="spec-json">OpenAPI 3 JSON</label><textarea id="spec-json" placeholder='{"openapi":"3.0.3","info":{},"paths":{}}'></textarea></div>${button('Save specification','save-spec','primary',`data-id="${el.dataset.id}"`)}`);
 if(a==='save-spec'){const x=await api('/api/connections/'+el.dataset.id+'/spec',{method:'POST',body:{spec:JSON.parse(document.querySelector('#spec-json').value)}});dialog.close();await refresh();toast(x.notice);if(x.runId)await showRun(x.runId);return}
 if(a==='review-rule')return await reviewRule(el.dataset.id);
 if(['approve-rule','draft-rule'].includes(a)){await api('/api/rules/'+el.dataset.id+'/review',{method:'POST',body:{approve:a==='approve-rule',confirm:document.querySelector('#review-confirm').checked,note:document.querySelector('#review-note').value}});dialog.close();await refresh();return toast('Rule review recorded')}
 if(a==='explain'){el.disabled=true;try{const x=await api('/api/runs/'+state.run.id+'/explain',{method:'POST',body:{findingId:el.dataset.id,language:el.dataset.language}});document.querySelector('#explanation-result').innerHTML=`<div class="detail-block space"><label>${e(x.mode.replaceAll('_',' '))}${x.cached?' · cached':''}</label><p>${e(x.summary)}</p><p style="margin-top:10px">${e(x.impact)}</p><p style="margin-top:10px">${e(x.fix)}</p><small>${e(x.reason||x.reviewStatus||'')} · ${date(x.generatedAt)}</small></div>`}finally{el.disabled=false}return}
 if(a==='new-schedule')return modal('Schedule an audit job',`<p>The local server must remain running. Uploaded evidence reviews are replays, not new bank measurements.</p><div class="field"><label for="schedule-kind">Job</label><select id="schedule-kind">${state.user.role==='operator'?'<option value="platform">Platform assurance</option>':''}<option value="evidence">Review imported evidence</option><option value="bank">Check sandbox readiness (no requests)</option></select></div><div class="field"><label for="schedule-pack">Evidence pack</label><select id="schedule-pack"><option value="">Select</option>${state.workspace.packs.map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label for="schedule-connection">Connection</label><select id="schedule-connection">${state.workspace.connections.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select></div><div class="field"><label for="schedule-minutes">Interval in minutes</label><input id="schedule-minutes" type="number" min="1" max="1440" value="60"></div>${button('Create schedule','save-schedule','primary')}`);
 if(a==='save-schedule'){await api('/api/schedules',{method:'POST',body:{kind:document.querySelector('#schedule-kind').value,packId:document.querySelector('#schedule-pack').value,connectionId:document.querySelector('#schedule-connection').value,minutes:Number(document.querySelector('#schedule-minutes').value)}});dialog.close();await refresh();return toast('Schedule created')}
 if(a==='delete-schedule'){await api('/api/schedules/'+el.dataset.id,{method:'DELETE'});return await refresh()}
 if(a==='new-gate')return modal('Evaluate a release candidate',`<p>This records a publication decision; it does not deploy or modify an external API.</p><div class="field"><label for="gate-name">Candidate name</label><input id="gate-name" placeholder="Adapter 0.1.0 candidate"></div><div class="field"><label for="gate-run">Completed evidence run</label><select id="gate-run"><option value="">Select a run</option>${state.workspace.runs.filter(r=>r.status==='completed').map(r=>`<option value="${r.id}">${e(r.name)} · ${date(r.finishedAt)}</option>`).join('')}</select></div>${button('Evaluate gate','save-gate','primary')}`);
 if(a==='save-gate'){const x=await api('/api/gates',{method:'POST',body:{name:document.querySelector('#gate-name').value,runId:document.querySelector('#gate-run').value}});dialog.close();await refresh();return toast(x.decision+': '+x.reason)}
 if(a==='source-update')return modal('Compare a candidate source snapshot',`<p>Text differences are proposals only. No new rule or mandate is automatically activated.</p><div class="field"><label for="update-title">Comparison label</label><input id="update-title" placeholder="Historical or simulated comparison"></div><div class="field"><label for="update-source">Pinned baseline</label><select id="update-source">${state.workspace.sources.map(s=>`<option value="${s.id}">${e(s.name)}</option>`).join('')}</select></div><div class="field"><label for="update-text">Candidate extracted text</label><textarea id="update-text"></textarea></div>${button('Compare snapshots','save-update','primary')}`);
 if(a==='save-update'){await api('/api/updates',{method:'POST',body:{title:document.querySelector('#update-title').value,sourceId:document.querySelector('#update-source').value,text:document.querySelector('#update-text').value}});dialog.close();await refresh();return toast('Draft comparison saved; rule activation still requires review')}
 }catch(err){if(el.dataset.action==='normalize'){const out=document.querySelector('#mapping-result');if(out)out.innerHTML=badge('Contract violation','fail')+`<div class="notice amber space">${e(err.message)}</div>`}toast(err.message)}});
dialog.addEventListener('click',ev=>{if(ev.target===dialog)dialog.close()});
setInterval(async()=>{if(state.user&&state.page==='detail'&&state.run&&['queued','running'].includes(state.run.status)&&!dialog.open){try{state.run=await api('/api/runs/'+state.run.id);if(state.run.status==='completed')state.workspace=await api('/api/workspace');render()}catch{}}},1300);
try{const result=await api('/api/me');activateSession(result);await refresh()}catch(err){if(state.user)toast('Workspace could not load: '+err.message);else login()}
